const base = $input.first().json.url_idealista;
const MAX_PAGINAS = 5;
const paginas = [];
for (let i = 1; i <= MAX_PAGINAS; i++) {
  const url = i === 1
    ? base + '?ordenado-por=fecha-publicacion-desc'
    : base + 'pagina-' + i + '.htm?ordenado-por=fecha-publicacion-desc';
  // pairedItem fijo en 0: sin esto se pierde el enlace al item de origen
  // (Config Busqueda) y $('Config Busqueda') falla mas adelante con
  // "Referenced node doesn't exist".
  paginas.push({ json: { url, pagina: i }, pairedItem: { item: 0 } });
}
return paginas;

// Fix: Fotocasa ignora '?page=N'/'?pageNumber=N' (confirmado con fetch directo,
// siempre SSR pagina 1). Paginacion real es un segmento de ruta: base + '/N'.
const base = $input.first().json.url_fotocasa;
const MAX_PAGINAS = 5;
const paginas = [];
for (let i = 1; i <= MAX_PAGINAS; i++) {
  const url = i === 1
    ? base + '?sortType=publicationDate'
    : base + '/' + i + '?sortType=publicationDate';
  // pairedItem fijo en 0: sin esto se pierde el enlace al item de origen
  // (Config Busqueda) y $('Config Busqueda') falla mas adelante con
  // "Referenced node doesn't exist".
  paginas.push({ json: { url, pagina: i }, pairedItem: { item: 0 } });
}
return paginas;

// Fotocasa rediseño su web: las clases re-Card-* ya no existen.
// El listado completo viene embebido como JSON en <script id="__initial_props__">,
// mucho mas estable que CSS selectors sobre clases utilitarias de Tailwind.
const items = [];

const tipoMap = {
  Flat: 'Piso',
  House_Chalet: 'Casa',
  Duplex: 'Duplex',
  Penthouse: 'Atico',
  Studio: 'Estudio',
  GroundFloor: 'Bajo'
};

function featureVal(features, key) {
  const f = (features || []).find(x => x.key === key);
  return f ? f.value : null;
}

const paginas = $input.all();

for (let p = 0; p < paginas.length; p++) {
  const html = paginas[p].json.data || '';
  const idx = html.indexOf('__initial_props__');
  if (idx === -1) continue;

  const scriptStart = html.indexOf('>', idx) + 1;
  const scriptEnd = html.indexOf('</script>', scriptStart);
  const jsonText = html.slice(scriptStart, scriptEnd);

  let props;
  try { props = JSON.parse(jsonText); } catch (e) { continue; }

  const realEstates = (props.initialSearch && props.initialSearch.result && props.initialSearch.result.realEstates) || [];

  for (const r of realEstates) {
    const m2 = featureVal(r.features, 'surface');
    const rooms = featureVal(r.features, 'rooms');
    const tipo = tipoMap[r.buildingSubtype] || tipoMap[r.buildingType] || 'Inmueble';
    const ubicacion = r.location || (r.address && r.address.city) || '';

    items.push({
      json: {
        titulo: tipo + ' en ' + ubicacion,
        url_relativa: (r.detail && r.detail['es-ES']) || '',
        precio: r.rawPrice || null,
        detalles: (m2 ? m2 + ' m² ' : '') + (rooms ? rooms + ' hab.' : ''),
        descripcion: r.description || '',
        telefono: r.phone || '',
        isProfessional: r.clientType === 'professional'
      },
      // Bug fix: pairedItem debe apuntar al item de entrada (la pagina) del que
      // se extrajo este anuncio. Sin esto n8n pierde la trazabilidad hacia atras
      // en el grafo y '$("Config Busqueda")' en el nodo Normalizar falla con
      // "Referenced node doesn't exist".
      pairedItem: { item: p }
    });
  }
}

return items;

function parseBool(val) {
  if (val === true || val === 'true') return true;
  if (Array.isArray(val) && val.length > 0) return true;
  return false;
}

function primero(val) {
  if (Array.isArray(val)) return val[0] || '';
  return val || '';
}

const d = $input.item.json;

function limpiarPrecio(texto) {
  if (!texto) return null;
  const soloNumeros = texto.toString().replace(/[^0-9]/g, '');
  return soloNumeros ? parseInt(soloNumeros) : null;
}

function extraerNumero(texto, regex) {
  if (!texto) return null;
  const m = texto.match(regex);
  return m ? parseInt(m[1]) : null;
}

function extraerPlanta(texto) {
  if (!texto) return null;
  const t = texto.toLowerCase();
  if (/\bático\b/.test(t)) return 'atico';
  if (/\bbajo\b/.test(t)) return 'bajo';
  if (/\bentresuelo\b/.test(t)) return 'entresuelo';
  const m = t.match(/(\d+)\s*ª\s*planta/);
  return m ? m[1] : null;
}

// Bug fix: url_relativa, titulo y precio llegan como array (returnArray:true en Extract), no string.
const urlRelativa = primero(d.url_relativa);
const titulo = primero(d.titulo);
const precioRaw = primero(d.precio);

// Bug fix: portal ya viene taggeado desde 'Tag Portal Idealista/Fotocasa' (confiable),
// antes se adivinaba buscando 'fotocasa' en una URL relativa que nunca la contiene.
const portal = d.portal || 'desconocido';
const urlBaseMap = { idealista: 'https://www.idealista.com', fotocasa: 'https://www.fotocasa.es' };
const urlBase = urlBaseMap[portal] || '';

const matchRef = urlRelativa.match(/(\d{6,})/);
const referencia = matchRef ? matchRef[1] : urlRelativa.slice(-15);

const detallesArray = d.detalles;
const detalles = Array.isArray(detallesArray) ? detallesArray.join(' ') : (detallesArray || '');
const m2 = extraerNumero(detalles, /(\d+)\s*m/i);
const habitaciones = extraerNumero(detalles, /(\d+)\s*hab/i);
const planta = extraerPlanta(detalles);

const telArray = d.telefono;
const telefono = Array.isArray(telArray) ? (telArray[0] || '') : (telArray || '');
const descArray = d.descripcion;
const descripcion = (Array.isArray(descArray) ? (descArray[0] || '') : (descArray || '')).slice(0, 500);

// Bug fix: 'zona' llegaba vacio y 'poblacion' traia el nombre de la comarca en
// vez del municipio real del anuncio. El titulo viene como "TIPO en UBICACION[,
// barrio, ...]"; el ultimo segmento tras las comas es el municipio real.
const partesTitulo = titulo.split(' en ');
const tipoInmuebleParsed = partesTitulo[0] || '';
const restoUbicacion = partesTitulo.slice(1).join(' en ');
const segmentosUbicacion = restoUbicacion.split(',').map(s => s.trim()).filter(Boolean);
const poblacionReal = segmentosUbicacion.length ? segmentosUbicacion[segmentosUbicacion.length - 1] : '';

return {
  json: {
    portal: portal,
    referencia: referencia,
    url: urlRelativa.startsWith('http') ? urlRelativa : urlBase + urlRelativa,
    titulo: titulo.trim(),
    precio: limpiarPrecio(precioRaw),
    m2: m2,
    habitaciones: habitaciones,
    planta: planta,
    poblacion: poblacionReal,
    zona: $('Config Busqueda').first().json.poblacion,
    tipoInmueble: tipoInmuebleParsed,
    lat: null,
    lng: null,
    fechaScrape: new Date().toISOString().slice(0, 10),
    telefono: telefono,
    descripcion: descripcion,
    isProfessional: parseBool(d.isProfessional)
  }
};

const nuevos = $('Normalizar').all();
const masterRows = $('Leer Inmuebles_Master').all().map(i => i.json).filter(r => r.id_interno);

function normalizarTexto(t) {
  if (!t) return '';
  return t.toString().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');
}

function calcularScore(a, b) {
  let score = 0;
  const bPrecio = b.precio_idealista || b.precio_fotocasa;
  if (a.precio && bPrecio) {
    const diffPct = Math.abs(a.precio - bPrecio) / bPrecio;
    if (diffPct < 0.02) score += 30;
  }
  if (a.m2 && b.m2 && Math.abs(a.m2 - parseFloat(b.m2)) <= 3) score += 25;
  if (a.habitaciones && b.habitaciones && a.habitaciones === parseInt(b.habitaciones)) score += 15;
  return score;
}

function plantaIncompatible(a, b) {
  // Distinta planta = distinta unidad fisica, casi siempre. Descalifica el
  // candidato aunque precio/m2/habitaciones coincidan (caso real detectado:
  // 2 pisos distintos en Mollet del Valles con mismo precio/m2/hab, pero uno
  // 'Bajo' y otro '5a planta').
  return !!(a.planta && b.planta && a.planta !== b.planta);
}

let masterActualizado = masterRows.map(r => ({...r}));
let siguienteId = masterRows.reduce((max, r) => {
  const n = parseInt((r.id_interno || 'INM-0000').split('-')[1] || 0);
  return n > max ? n : max;
}, 0);

const salidaMaster = [];
const salidaHistorico = [];
const hoy = new Date().toISOString().slice(0, 10);

for (const item of nuevos) {
  const d = item.json;
  const campoRef = 'ref_' + d.portal;
  const campoPrecio = 'precio_' + d.portal;
  const campoLink = 'link_' + d.portal;

  let match = masterActualizado.find(m => m[campoRef] && m[campoRef] === d.referencia);

  if (!match) {
    const candidatos = masterActualizado.filter(m => normalizarTexto(m.poblacion) === normalizarTexto(d.poblacion));
    let mejor = null, mejorScore = 0;
    for (const c of candidatos) {
      if (plantaIncompatible(d, c)) continue;
      const s = calcularScore(d, c);
      if (s > mejorScore) { mejorScore = s; mejor = c; }
    }
    if (mejor && mejorScore >= 70) match = mejor;
  }

  if (match) {
    match[campoRef] = d.referencia;
    if (d.url) match[campoLink] = d.url;
    match.ultimaFechaVista = hoy;

    if (!match._vistoEnEsteLote) {
      match.vecesVisto = (parseInt(match.vecesVisto) || 0) + 1;
      match._vistoEnEsteLote = true;
    }
    match.activo = true;
    if (d.telefono) match.telefono = d.telefono;
    if (d.descripcion) match.descripcion = d.descripcion;
    if (d.isProfessional) match.isProfessional = true;
    if (d.planta && !match.planta) match.planta = d.planta;

    // Bug 2 Fix: diasPublicado calculado desde fecha, no desde campo stale de Sheets
    if (match.fechaPrimeraCaptacion) {
      const ms = new Date(hoy) - new Date(match.fechaPrimeraCaptacion);
      match.diasPublicado = Math.floor(ms / (1000 * 60 * 60 * 24));
    }
    match.numPortales = [match.ref_idealista, match.ref_fotocasa].filter(Boolean).length;

    const precioAnterior = parseFloat(match[campoPrecio]);
    const precioNuevo = d.precio;
    // Bug 1 Fix: Solo registrar en historico si el precio BAJÓ (no subidas)
    if (precioAnterior && precioNuevo && precioAnterior !== precioNuevo) {
      if (precioAnterior > precioNuevo) {
        match._haBajadoPrecio = true;
        salidaHistorico.push({
          json: {
            id_interno: match.id_interno,
            portal: d.portal,
            fecha: hoy,
            precio: precioNuevo,
            precio_anterior: precioAnterior,
            precio_m2: d.m2 ? Math.round(precioNuevo / d.m2) : ''
          }
        });
      }
      // Siempre actualizamos el precio (aunque haya subido)
      match[campoPrecio] = precioNuevo;
    } else if (precioNuevo && !precioAnterior) {
      match[campoPrecio] = precioNuevo;
    }
  } else {
    siguienteId += 1;
    const idInterno = 'INM-' + String(siguienteId).padStart(4, '0');
    match = {
      id_interno: idInterno,
      descripcion: d.descripcion || '',
      poblacion: d.poblacion || '',
      zona: d.zona || '',
      tipo_inmueble: d.tipoInmueble || '',
      m2: d.m2 || '',
      habitaciones: d.habitaciones || '',
      planta: d.planta || '',
      ref_idealista: d.portal === 'idealista' ? d.referencia : '',
      ref_fotocasa: d.portal === 'fotocasa' ? d.referencia : '',
      precio_idealista: d.portal === 'idealista' ? d.precio || '' : '',
      precio_fotocasa: d.portal === 'fotocasa' ? d.precio || '' : '',
      link_idealista: d.portal === 'idealista' ? d.url || '' : '',
      link_fotocasa: d.portal === 'fotocasa' ? d.url || '' : '',
      fechaPrimeraCaptacion: hoy,
      diasPublicado: 0,
      numPortales: 1,
      vecesVisto: 1,
      ultimaFechaVista: hoy,
      activo: true,
      telefono: d.telefono || '',
      isProfessional: d.isProfessional || false,
      enviadoAEspoCRM: false,
      _vistoEnEsteLote: true
    };
    masterActualizado.push(match);
  }

  const idx = salidaMaster.findIndex(x => x.json.id_interno === match.id_interno);
  if (idx === -1) salidaMaster.push({ json: { ...match } });
  else salidaMaster[idx] = { json: { ...match } };
}

salidaMaster.forEach(x => { delete x.json._vistoEnEsteLote; });

return [
  ...salidaMaster.map(x => ({ json: { ...x.json, _tabla: 'master' } })),
  ...salidaHistorico.map(x => ({ json: { ...x.json, _tabla: 'historico' } }))
];

// Bug fix: htmlExtract con returnArray:true da 1 item POR PAGINA con arrays paralelos
// (30 anuncios comprimidos en 1 item), no 1 item por anuncio. Sin esto, solo el indice [0]
// de cada pagina se procesaba, se perdian silenciosamente ~29/30 anuncios por pagina.
// Aqui se transpone: 1 item de entrada (pagina) -> N items de salida (1 por anuncio).
const items = [];
const paginas = $input.all();

for (let p = 0; p < paginas.length; p++) {
  const d = paginas[p].json;
  const n = Array.isArray(d.titulo) ? d.titulo.length : 0;

  for (let i = 0; i < n; i++) {
    items.push({
      json: {
        titulo: Array.isArray(d.titulo) ? d.titulo[i] : d.titulo,
        url_relativa: Array.isArray(d.url_relativa) ? d.url_relativa[i] : d.url_relativa,
        precio: Array.isArray(d.precio) ? d.precio[i] : d.precio,
        detalles: Array.isArray(d.detalles) ? d.detalles[i] : d.detalles,
        descripcion: Array.isArray(d.descripcion) ? d.descripcion[i] : d.descripcion,
        telefono: Array.isArray(d.telefono) ? d.telefono[i] : d.telefono,
        isProfessional: Array.isArray(d.isProfessional) ? d.isProfessional[i] : d.isProfessional,
        portal: 'idealista'
      },
      // Bug fix: pairedItem debe apuntar al item de entrada (la pagina) del que
      // se extrajo este anuncio. Sin esto n8n pierde la trazabilidad hacia atras
      // en el grafo y '$("Config Busqueda")' en el nodo Normalizar falla con
      // "Referenced node doesn't exist".
      pairedItem: { item: p }
    });
  }
}

return items;
